export interface ConnectorConfig {
  asanaPersonalAccessToken: string
  workspaceGid: string
  fetch?: typeof fetch
}

export interface JotformSubmissionPayload {
  formId: string
  firstName?: string
  lastName?: string
  email?: string
  answers: Record<string, string>
}

export interface AsanaTaskResult {
  gid: string
  name: string
  notes: string
  resourceType: string
}

function validatePayload(payload: JotformSubmissionPayload): void {
  if (!payload.formId) {
    throw new Error('Missing required field: formId')
  }
  if (!payload.answers || typeof payload.answers !== 'object') {
    throw new Error('Missing required field: answers')
  }
}

function buildTaskName(payload: JotformSubmissionPayload): string {
  const firstName = payload.firstName?.trim()
  const lastName = payload.lastName?.trim()
  if (firstName || lastName) {
    return `${firstName ?? ''} ${lastName ?? ''}`.trim()
  }
  return `Jotform Submission ${payload.formId}`
}

function buildTaskNotes(payload: JotformSubmissionPayload): string {
  const lines: string[] = []
  if (payload.email) {
    lines.push(`Email: ${payload.email}`)
  }
  if (payload.answers && Object.keys(payload.answers).length > 0) {
    lines.push(`Answers: ${JSON.stringify(payload.answers)}`)
  }
  return lines.join('\n')
}

export async function handle(
  payload: JotformSubmissionPayload,
  config: ConnectorConfig
): Promise<AsanaTaskResult> {
  validatePayload(payload)

  const fetchImpl = config.fetch ?? fetch
  const url = 'https://app.asana.com/api/1.0/tasks'
  const taskName = buildTaskName(payload)
  const taskNotes = buildTaskNotes(payload)

  const requestBody = {
    data: {
      name: taskName,
      notes: taskNotes,
      workspace: config.workspaceGid,
    },
  }

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.asanaPersonalAccessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(requestBody),
  })

  if (!response.ok) {
    throw new Error(`Asana API error: ${response.status} ${response.statusText} for POST ${url}`)
  }

  const responseData = (await response.json()) as { data: AsanaTaskResult }
  return responseData.data
}

