import { handle, JotformSubmissionPayload, ConnectorConfig } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

