describe('handle', () => {
  it('creates a task with correct field mapping on happy path', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://app.asana.com/api/1.0/tasks')
      expect(req.headers.get('authorization')).toBe('Bearer test-token')
      expect(req.json).toEqual({
        data: {
          name: 'John Doe',
          notes: 'Email: john.doe@example.com\nAnswers: {"question1":"Answer 1","question2":"Answer 2"}',
          workspace: 'WORKSPACE_GID',
        },
      })
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    const payload: JotformSubmissionPayload = {
      formId: '1234567890',
      firstName: 'John',
      lastName: 'Doe',
      email: 'john.doe@example.com',
      answers: { question1: 'Answer 1', question2: 'Answer 2' },
    }

    const result = await handle(payload, {
      asanaPersonalAccessToken: 'test-token',
      workspaceGid: 'WORKSPACE_GID',
      fetch,
    })

    expect(result.gid).toBe('987654321')
    expect(result.name).toBe('John Doe')
    expect(calls.length).toBe(1)
  })

  it('uses formId as task name when firstName and lastName are missing', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      expect(req.json).toEqual({
        data: {
          name: 'Jotform Submission 999',
          notes: 'Answers: {"q":"a"}',
          workspace: 'WORKSPACE_GID',
        },
      })
      return jsonResponse({
        data: { gid: '111', name: 'Jotform Submission 999', notes: 'Answers: {"q":"a"}', resource_type: 'task' },
      })
    })

    const payload: JotformSubmissionPayload = {
      formId: '999',
      answers: { q: 'a' },
    }

    const result = await handle(payload, {
      asanaPersonalAccessToken: 'test-token',
      workspaceGid: 'WORKSPACE_GID',
      fetch,
    })

    expect(result.name).toBe('Jotform Submission 999')
    expect(calls.length).toBe(1)
  })

  it('includes only email in notes when answers is empty', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      expect(req.json).toEqual({
        data: {
          name: 'Jane Smith',
          notes: 'Email: jane@example.com',
          workspace: 'WORKSPACE_GID',
        },
      })
      return jsonResponse({
        data: { gid: '222', name: 'Jane Smith', notes: 'Email: jane@example.com', resource_type: 'task' },
      })
    })

    const payload: JotformSubmissionPayload = {
      formId: '888',
      firstName: 'Jane',
      lastName: 'Smith',
      email: 'jane@example.com',
      answers: {},
    }

    const result = await handle(payload, {
      asanaPersonalAccessToken: 'test-token',
      workspaceGid: 'WORKSPACE_GID',
      fetch,
    })

    expect(result.notes).toBe('Email: jane@example.com')
    expect(calls.length).toBe(1)
  })

  it('throws descriptive error when formId is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { answers: { q: 'a' } } as unknown as JotformSubmissionPayload

    await expect(handle(payload, { asanaPersonalAccessToken: 't', workspaceGid: 'w', fetch })).rejects.toThrow(
      'Missing required field: formId'
    )
  })

  it('throws descriptive error when answers is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { formId: '123' } as unknown as JotformSubmissionPayload

    await expect(handle(payload, { asanaPersonalAccessToken: 't', workspaceGid: 'w', fetch })).rejects.toThrow(
      'Missing required field: answers'
    )
  })

  it('throws error with status and endpoint on non-2xx response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    const payload: JotformSubmissionPayload = {
      formId: '123',
      answers: { q: 'a' },
    }

    await expect(
      handle(payload, { asanaPersonalAccessToken: 'bad-token', workspaceGid: 'w', fetch })
    ).rejects.toThrow('Asana API error: 401 Unauthorized for POST https://app.asana.com/api/1.0/tasks')
  })

  it('throws error with status and endpoint on 500 response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Server Error' }, 500))
    const payload: JotformSubmissionPayload = {
      formId: '123',
      answers: { q: 'a' },
